-- mistri store layout: decisions, postgres, version 1. Generated by scripts/store-layouts.mjs; never edit by hand.
SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;
CREATE SCHEMA mistri;
SET default_tablespace = '';
SET default_table_access_method = heap;
CREATE TABLE mistri.decision_meta (
    singleton integer NOT NULL,
    version integer NOT NULL,
    CONSTRAINT decision_meta_singleton_check CHECK ((singleton = 1)),
    CONSTRAINT decision_meta_version_check CHECK ((version = 1))
);
CREATE TABLE mistri.decision_record (
    id text NOT NULL COLLATE pg_catalog."C",
    app text NOT NULL COLLATE pg_catalog."C",
    tenant text NOT NULL COLLATE pg_catalog."C",
    decision text NOT NULL,
    contract_version integer NOT NULL,
    resource text NOT NULL,
    record_key text NOT NULL,
    field text NOT NULL,
    trigger text NOT NULL,
    provider text NOT NULL,
    model text NOT NULL,
    model_version text NOT NULL,
    inputs_digest text NOT NULL,
    input_fields text NOT NULL,
    choices_digest text NOT NULL,
    answer text,
    probability double precision,
    outcome text NOT NULL,
    outcome_reason text NOT NULL,
    corrected_to text,
    outcome_by text NOT NULL,
    outcome_at text NOT NULL,
    latency_ms integer NOT NULL,
    cost_micros bigint NOT NULL,
    units integer NOT NULL,
    created_at text NOT NULL,
    CONSTRAINT decision_record_answer_check CHECK (((answer IS NULL) OR (octet_length(answer) <= 65536))),
    CONSTRAINT decision_record_app_check CHECK ((octet_length(app) <= 128)),
    CONSTRAINT decision_record_outcome_check CHECK ((outcome = ANY (ARRAY['applied'::text, 'suggested'::text, 'accepted'::text, 'corrected'::text, 'ignored'::text, 'below'::text, 'none'::text]))),
    CONSTRAINT decision_record_probability_check CHECK (((probability IS NULL) OR ((probability >= (0)::double precision) AND (probability <= (1)::double precision)))),
    CONSTRAINT decision_record_tenant_check CHECK ((octet_length(tenant) <= 128))
);
CREATE TABLE mistri.decision_usage (
    app text NOT NULL COLLATE pg_catalog."C",
    tenant text NOT NULL COLLATE pg_catalog."C",
    day text NOT NULL,
    calls bigint NOT NULL,
    units bigint NOT NULL,
    cost_micros bigint NOT NULL
);
CREATE TABLE mistri.switch_meta (
    singleton integer NOT NULL,
    version integer NOT NULL,
    CONSTRAINT switch_meta_singleton_check CHECK ((singleton = 1)),
    CONSTRAINT switch_meta_version_check CHECK ((version = 1))
);
CREATE TABLE mistri.switch_tenant (
    app text NOT NULL COLLATE pg_catalog."C",
    tenant text NOT NULL COLLATE pg_catalog."C",
    feature text NOT NULL COLLATE pg_catalog."C",
    enabled integer NOT NULL,
    consent text NOT NULL,
    changed_at text NOT NULL,
    CONSTRAINT switch_tenant_app_check CHECK ((octet_length(app) <= 128)),
    CONSTRAINT switch_tenant_consent_check CHECK ((octet_length(consent) <= 2000)),
    CONSTRAINT switch_tenant_enabled_check CHECK ((enabled = ANY (ARRAY[0, 1]))),
    CONSTRAINT switch_tenant_feature_check CHECK ((octet_length(feature) <= 64)),
    CONSTRAINT switch_tenant_tenant_check CHECK ((octet_length(tenant) <= 128))
);
INSERT INTO mistri.decision_meta (singleton, version) VALUES (1, 1);
INSERT INTO mistri.switch_meta (singleton, version) VALUES (1, 1);
ALTER TABLE ONLY mistri.decision_meta
    ADD CONSTRAINT decision_meta_pkey PRIMARY KEY (singleton);
ALTER TABLE ONLY mistri.decision_record
    ADD CONSTRAINT decision_record_pkey PRIMARY KEY (id);
ALTER TABLE ONLY mistri.decision_usage
    ADD CONSTRAINT decision_usage_pkey PRIMARY KEY (app, tenant, day);
ALTER TABLE ONLY mistri.switch_meta
    ADD CONSTRAINT switch_meta_pkey PRIMARY KEY (singleton);
ALTER TABLE ONLY mistri.switch_tenant
    ADD CONSTRAINT switch_tenant_pkey PRIMARY KEY (app, tenant, feature);
CREATE INDEX __mistri_decision_record_age ON mistri.decision_record USING btree (app, created_at);
CREATE INDEX __mistri_decision_record_on ON mistri.decision_record USING btree (app, tenant, resource, record_key, created_at);
